//! The calibration profile the estimator inverts: generated by tools/calib/make_profile.py and
//! committed at assets/audio-profile.json.

use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::Table;

const DEFAULT: &str = include_str!("../assets/audio-profile.json");

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct AudioProfile {
    pub version: u32,
    #[serde(default)]
    pub sources: Vec<String>,
    pub ild: IldTables,
    /// Level change at a hard pan: measured level = on-axis level + this × sin²(rel).
    pub lateral_level_db: f64,
    /// Level uncertainty used to widen each distance into a range.
    pub level_tolerance_db: f64,
    /// Lateral-corrected level100 per distance, every band; informational.
    pub level_table: Table,
    pub switch: Switch,
    /// Level → distance inside the switch: monotonic.
    pub inside_table: Table,
    /// Level → distance beyond it: dips at ~130 m, so one level can mean two distances.
    pub beyond_table: Table,
}

/// |sin(rel)| → lateral ILD magnitude, dB.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct IldTables {
    /// Below this distance the mech/LFE layers change the panning, so `near` applies.
    pub near_max_m: f64,
    pub near: Table,
    pub far: Table,
}

/// The < 125 m test: see make_profile.py `switch` for how the band and early/late cut are chosen.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Switch {
    pub distance_m: f64,
    /// hi_lo inside this band means the near clip is present.
    pub hi_lo_band_db: [f64; 2],
    /// In the band but early/late at or above this: the distant clip dominates; ambiguous.
    pub early_late_far_db: f64,
}

impl AudioProfile {
    /// The committed profile.
    pub fn builtin() -> Self {
        Self::parse(DEFAULT).expect("assets/audio-profile.json is valid")
    }

    pub fn load(path: &Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))?;
        Self::parse(&text).map_err(|e| format!("{}: {e}", path.display()))
    }

    /// `path` when it exists and parses, else the built-in profile (with a warning if it was unusable).
    pub fn load_or_builtin(path: &Path) -> Self {
        if !path.is_file() {
            return Self::builtin();
        }
        Self::load(path).unwrap_or_else(|e| {
            tracing::warn!(error = %e, "Audio profile unusable; using the built-in one");
            Self::builtin()
        })
    }

    pub fn parse(text: &str) -> Result<Self, String> {
        let profile: Self = serde_json::from_str(text).map_err(|e| e.to_string())?;
        profile.ild.near.validate("ild.near")?;
        profile.ild.far.validate("ild.far")?;
        profile.inside_table.validate("inside_table")?;
        profile.beyond_table.validate("beyond_table")?;
        Ok(profile)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_builtin_profile_parses() {
        let p = AudioProfile::builtin();
        assert!(p.switch.hi_lo_band_db[0] < p.switch.hi_lo_band_db[1]);
    }
}
